WHITESPACE = " \t\n\r"
ESCAPES = '"\\/bfnrtu'
HEX = "0123456789abcdefABCDEF"
OPENER = {"}": "{", "]": "["}


def json_stream_status(streams):
    return [_status(chunks) for chunks in streams]


def _status(chunks):
    stack = []              # brackets still open
    started = done = False
    in_str = escaped = False
    hex_left = 0            # hex digits still owed after a \u
    complete_at = None
    pos = 0                 # index of the current character in the whole stream
    for k, chunk in enumerate(chunks):
        for ch in chunk:
            if in_str:
                if hex_left:
                    if ch not in HEX:
                        return ("invalid", pos)
                    hex_left -= 1
                elif escaped:
                    if ch not in ESCAPES:
                        return ("invalid", pos)
                    escaped = False
                    if ch == "u":
                        hex_left = 4
                elif ch == '"':
                    in_str = False
                elif ch == "\\":
                    escaped = True
                elif ch < " ":
                    return ("invalid", pos)
            elif ch in WHITESPACE:
                pass
            elif done:
                return ("invalid", pos)          # only whitespace may follow a complete response
            elif ch == "{" or ch == "[":
                stack.append(ch)
                started = True
            elif not started:
                return ("invalid", pos)          # must start with { or [
            elif ch == "}" or ch == "]":
                if stack[-1] != OPENER[ch]:
                    return ("invalid", pos)
                stack.pop()
                if not stack:
                    done = True
                    complete_at = k
            elif ch == '"':
                in_str = True
            pos += 1
    if done:
        return ("complete", complete_at)
    return ("incomplete", len(stack))

